Coding-Test/[260612]-문자열-다루기-기본.content:
코딩테스트 연습 - 문자열 다루기 기본 | 프로그래머스 스쿨
[ 템플릿 코드 ]
#include &lt;string&gt;
#include &lt;vector&gt;

using namespace std;

bool solution(string s) {
    bool answer = true;
    return answer;
}
[ 풀이 ]
#include &lt;string&gt;

using namespace std;

bool solution(string s)
{
    if (s.length() != 4 &amp;&amp; s.length() != 6)
    {
        return false;
    }
    for (char c : s)
    {
        if (c &lt; &#039;0&#039; || c &gt; &#039;9&#039;)
        {
            return false;
        }
    }

    return true;
}
[ 해설 ]
#include &lt;string&gt;

using namespace std;

bool solution(string s)
{
    // 길이가 4도 아니고 6도 아니면 false
    if (s.length() != 4 &amp;&amp; s.length() != 6)
    {
        return false;
    }

    // 문자열의 모든 문자를 확인
    for (char c : s)
    {
        // 숫자가 아니면 false
