    // arr1.size()는 행의 개수
    for (int i = 0; i &lt; arr1.size(); i++)
    {
        // 현재 행의 모든 열(Column)을 순회
        // arr1[i].size()는 i번째 행의 열 개수
        for (int j = 0; j &lt; arr1[i].size(); j++)
        {
