[ 해설 ]
int solution(int n)
{
    // 3진수를 저장할 문자열
    // 나머지를 순서대로 넣기 때문에 뒤집힌 3진수가 저장된다.
    string s = &quot;&quot;;

    // n이 0이 될 때까지 반복
    while (n &gt; 0)
    {
        // n을 3으로 나눈 나머지를 구한다.
        // + &#039;0&#039;을 해서 숫자를 문자(&#039;0&#039;, &#039;1&#039;, &#039;2&#039;)로 변환한다.
        // 예) 2 + &#039;0&#039; -&gt; &#039;2&#039;
        //
        // 45일 경우
        // 45 % 3 = 0 -&gt; s = &quot;0&quot;
        // 15 % 3 = 0 -&gt; s = &quot;00&quot;
        // 5  % 3 = 2 -&gt; s = &quot;002&quot;
        // 1  % 3 = 1 -&gt; s = &quot;0021&quot;
        //
        // 결과적으로 원래 3진수(1200)가 아닌
        // 뒤집힌 3진수(0021)가 저장된다.
        s += (n % 3) + &#039;0&#039;;

        // 다음 자릿수를 계산하기 위해 3으로 나눈 몫을 저장
        //
        // 45 -&gt; 15
        // 15 -&gt; 5
        // 5  -&gt; 1
        // 1  -&gt; 0
        n /= 3;
    }

    // 최종 결과(10진수)를 저장할 변수
    int answer = 0;

    // 문자열에 저장된 뒤집힌 3진수를 한 글자씩 확인
    for (char c : s)
    {
        // 문자 숫자를 실제 숫자로 변환
        //
        // &#039;0&#039; - &#039;0&#039; = 0
        // &#039;1&#039; - &#039;0&#039; = 1
        // &#039;2&#039; - &#039;0&#039; = 2
        //
        // answer * 3 은 현재 값을 한 자리 왼쪽으로 이동시키는 것과 같다.
        //
        // 예) s = &quot;0021&quot;
        //
        // 첫 번째 문자 &#039;0&#039;
        // answer = 0 * 3 + 0 = 0
        //
        // 두 번째 문자 &#039;0&#039;
        // answer = 0 * 3 + 0 = 0
        //
        // 세 번째 문자 &#039;2&#039;
        // answer = 0 * 3 + 2 = 2
        //
        // 네 번째 문자 &#039;1&#039;
        // answer = 2 * 3 + 1 = 7
        //
        // 최종 결과 = 7
        answer = answer * 3 + (c - &#039;0&#039;);
    }

    // 계산된 10진수 결과 반환
    return answer;
}
[ 타 답안 ]
#include &lt;string&gt;
#include &lt;vector&gt;

using namespace std;

int solution(int n) {
    // 최종 결과를 저장할 변수
    int answer = 0;

    // 3진수의 각 자릿수를 저장할 벡터
    vector&lt;int&gt; v;

    // n을 3진수로 변환
    while(n &gt; 0){
        // 3으로 나눈 나머지를 벡터에 저장
        //
        // 예) n = 45
        // 45 % 3 = 0 -&gt; [0]
        // 15 % 3 = 0 -&gt; [0, 0]
        // 5  % 3 = 2 -&gt; [0, 0, 2]
        // 1  % 3 = 1 -&gt; [0, 0, 2, 1]
        //
        // 이미 뒤집힌 형태로 저장된다.
        v.push_back(n % 3);

        // 다음 자릿수 계산을 위해 3으로 나눈 몫 저장
        n /= 3;
    }

    // 현재 자릿값
    //
    // 3^0 = 1
    // 3^1 = 3
    // 3^2 = 9
    // ...
    int k = 1;

    // 벡터가 빌 때까지 반복
    while(!v.empty()) {

        // 벡터의 마지막 원소를 꺼내 사용
        //
        // [0,0,2,1]
        // 처음에는 1
        answer += k * v.back();

        // 사용한 마지막 원소 제거
        v.pop_back();

        // 다음 자릿수로 이동
        //
        // 1 -&gt; 3 -&gt; 9 -&gt; 27 ...
        k *= 3;
    }

    return answer;
}
