#include &lt;string&gt;  // string 자료형 사용
#include &lt;vector&gt;  // 현재 코드에서는 사용하지 않음

using namespace std; // std::string, std::vector 등을 std 없이 사용

string solution(string s)
{
    int count = 0; // 현재 단어에서 몇 번째 문자인지 저장
                   // 공백을 만나면 다시 0으로 초기화

    // 문자열의 처음부터 끝까지 반복
    for(int i = 0; i &lt; s.size(); i++)
    {
        // 현재 문자가 공백인지 확인
        if(s[i] == &#039; &#039;)
        {
            count = 0; // 새로운 단어가 시작되므로 인덱스 초기화
        }
        else
        {
            // 현재 단어에서 짝수 번째 문자라면
            if(count % 2 == 0)
            {
                // 현재 문자가 소문자인지 확인
                if(s[i] &gt;= &#039;a&#039; &amp;&amp; s[i] &lt;= &#039;z&#039;)
                    s[i] -= 32; // 소문자를 대문자로 변환
            }
            else // 현재 단어에서 홀수 번째 문자라면
            {
                // 현재 문자가 대문자인지 확인
                if(s[i] &gt;= &#039;A&#039; &amp;&amp; s[i] &lt;= &#039;Z&#039;)
                    s[i] += 32; // 대문자를 소문자로 변환
            }

            // 공백이 아닌 문자를 처리했으므로
            // 현재 단어의 문자 순서를 1 증가
            count++;
        }
    }

    // 변환이 완료된 문자열 반환
    return s;
}
