#include &lt;string&gt;      // string(문자열) 자료형을 사용하기 위한 헤더 파일
using namespace std;   // std::string 대신 string처럼 std::를 생략해서 사용

string solution(string s) {

    int idx = 0;       // 현재 단어에서 몇 번째 문자인지 저장하는 변수
                       // 단어가 바뀌면 다시 0부터 시작

    // 문자열 s의 문자를 처음부터 끝까지 하나씩 꺼내서 c에 저장
    // auto : 자료형을 자동으로 추론 (여기서는 char)
    // &amp; : 참조(Reference), c를 수정하면 원본 문자열 s도 함께 수정됨
    for(auto&amp; c : s) {

        // idx &amp; 1
        // -&gt; idx가 홀수이면 1(true)
        // -&gt; idx가 짝수이면 0(false)
        //
        // 삼항 연산자
        // 조건 ? 참일때 : 거짓일때
        //
        // idx가 홀수면 tolower(c) 실행
        // -&gt; 현재 문자를 소문자로 변경
        //
        // idx가 짝수면 toupper(c) 실행
        // -&gt; 현재 문자를 대문자로 변경
        //
        // 변경된 문자를 다시 c에 저장
        c = idx &amp; 1 ? tolower(c) : toupper(c);

        // 현재 문자가 공백인지 확인
        //
        // 공백이라면
        // -&gt; 다음 문자는 새로운 단어의 첫 글자
        // -&gt; idx를 0으로 초기화
        //
        // 공백이 아니라면
        // -&gt; 현재 단어의 다음 문자로 이동
        // -&gt; idx를 1 증가
        //
        // 삼항 연산자 형태
        // 조건 ? 참일때값 : 거짓일때값
        idx = c == &#039; &#039; ? 0 : idx + 1;
    }

    // 변환이 완료된 문자열 반환
    return s;
}
