[ 해설 ]
#include &lt;string&gt;
using namespace std;

int solution(string t, string p)
{
    // 조건을 만족하는 부분 문자열의 개수를 저장
    int answer = 0;

    // p의 길이 저장
    // 예) p = &quot;271&quot; 이면 len = 3
    int len = p.length();

    // 부분 문자열의 시작 위치를 하나씩 이동
    // 예) t = &quot;3141592&quot;, len = 3
    // 시작 위치는 0, 1, 2, 3, 4 까지 가능
    for(int i = 0; i &lt;= t.length() - len; i++)
    {
        // 부분 문자열을 저장할 빈 문자열 생성
        string sub = &quot;&quot;;

        // 현재 위치(i)부터 len개의 문자를 직접 붙여서
        // 부분 문자열 생성
        //
        // 예)
        // i = 0 이면
        // t[0] = &#039;3&#039;
        // t[1] = &#039;1&#039;
        // t[2] = &#039;4&#039;
        //
        // 결과 : sub = &quot;314&quot;
        for(int j = i; j &lt; i + len; j++)
        {
            // 현재 문자를 문자열 뒤에 추가
            sub += t[j];
        }

        // 만들어진 부분 문자열이 p보다 작거나 같은지 비교
        //
        // 예)
        // sub = &quot;141&quot;
        // p   = &quot;271&quot;
        //
        // &quot;141&quot; &lt;= &quot;271&quot; 이므로 참
        if(sub &lt;= p)
        {
            // 조건을 만족하면 개수 증가
            answer++;
        }
    }

    // 최종 개수 반환
    return answer;
}
