#include &lt;string&gt;

int solution(std::string t, std::string p) {
    int answer = 0;

    // 시작 위치(i)를 한 칸씩 이동하며 검사
    for(int i = 0; i &lt;= t.size() - p.size(); i++)
    {
        // substr(시작위치, 글자수)
        // 현재 위치(i)부터 p의 길이만큼 문자열을 잘라냄
        //
        // 예)
        // t = &quot;3141592&quot;
        // p = &quot;271&quot; (길이 3)
        //
        // i = 0 -&gt; t.substr(0, 3) -&gt; &quot;314&quot;
        // i = 1 -&gt; t.substr(1, 3) -&gt; &quot;141&quot;
        // i = 2 -&gt; t.substr(2, 3) -&gt; &quot;415&quot;
        // i = 3 -&gt; t.substr(3, 3) -&gt; &quot;159&quot;
        // i = 4 -&gt; t.substr(4, 3) -&gt; &quot;592&quot;
        //
        // 잘라낸 부분 문자열이 p보다 작거나 같으면
