#include &lt;vector&gt;
#include &lt;algorithm&gt;

using namespace std;

int solution(vector&lt;vector&lt;int&gt;&gt; sizes)
{
    // 지갑에 필요한 최대 가로 길이
    int maxWidth = 0;

    // 지갑에 필요한 최대 세로 길이
    int maxHeight = 0;

    // 모든 명함 확인
    for (auto card : sizes)
    {
        // 명함의 긴 변
        int width = max(card[0], card[1]);

        // 명함의 짧은 변
        int height = min(card[0], card[1]);

        // 지금까지 나온 긴 변 중 가장 큰 값 저장
        maxWidth = max(maxWidth, width);

        // 지금까지 나온 짧은 변 중 가장 큰 값 저장
        maxHeight = max(maxHeight, height);
    }

    // 모든 명함이 들어가는 최소 지갑 크기
    return maxWidth * maxHeight;
