#include &lt;string&gt;
#include &lt;vector&gt;
#include &lt;iostream&gt;

using namespace std;

int solution(vector&lt;vector&lt;int&gt;&gt; sizes)
{
    // 정답(지갑 크기)을 저장할 변수
    int answer = 0;

    // w : 모든 명함의 짧은 변들 중 최대값
    // h : 모든 명함의 긴 변들 중 최대값
    int w = 0, h = 0;

    // 모든 명함 확인
    for (int i = 0; i &lt; sizes.size(); i++)
    {
        // 현재 명함의 짧은 변 구하기
        // min(가로, 세로)를 사용
        // 지금까지 나온 짧은 변 중 가장 큰 값 저장
        w = max(w, min(sizes[i][0], sizes[i][1]));

        // 현재 명함의 긴 변 구하기
        // max(가로, 세로)를 사용
        // 지금까지 나온 긴 변 중 가장 큰 값 저장
        h = max(h, max(sizes[i][0], sizes[i][1]));
    }

    // 필요한 지갑의 가로와 세로를 곱해 넓이 계산
    answer = w * h;

    // 최소 지갑 크기 반환
    return answer;
