#include &lt;string&gt;      // string 클래스와 stoi() 함수를 사용하기 위한 헤더
using namespace std;   // std::를 생략하기 위해 사용

// 문자열 s를 받아 원래의 숫자로 변환하는 함수
int solution(string s)
{
    // 최종적으로 숫자만 저장될 문자열
    // 예) &quot;one4seveneight&quot; -&gt; &quot;1478&quot;
    string answer = &quot;&quot;;

    // 영단어를 한 글자씩 모아둘 임시 문자열
    // 예) &quot;o&quot; -&gt; &quot;on&quot; -&gt; &quot;one&quot;
    string temp = &quot;&quot;;

    // 문자열의 처음부터 끝까지 한 글자씩 확인
    for (int i = 0; i &lt; s.size(); i++)
    {
        // 현재 문자가 숫자인지 확인
        // 문자 &#039;0&#039; ~ &#039;9&#039;의 아스키코드를 이용한 비교
        if (s[i] &gt;= &#039;0&#039; &amp;&amp; s[i] &lt;= &#039;9&#039;)
        {
            // 숫자라면 그대로 결과 문자열에 추가
            // 예)
            // answer = &quot;14&quot;
            // s[i] = &#039;5&#039;
            // 결과 -&gt; &quot;145&quot;
            answer += s[i];
        }
        // 숫자가 아니라면 영어 문자
        else
        {
            // 현재 문자를 temp 문자열 뒤에 추가
            // 예)
            // temp = &quot;o&quot;
            // temp = &quot;on&quot;
            // temp = &quot;one&quot;
            temp += s[i];

            // temp가 &quot;zero&quot;가 되면
            if (temp == &quot;zero&quot;)
            {
                // 결과 문자열에 숫자 0 추가
                answer += &#039;0&#039;;

                // 다음 영단어를 저장하기 위해 temp 초기화
                temp = &quot;&quot;;
            }

            // temp가 &quot;one&quot;이 되면
            else if (temp == &quot;one&quot;)
            {
                // 숫자 1 추가
                answer += &#039;1&#039;;

                // temp 비우기
                temp = &quot;&quot;;
            }

            // temp가 &quot;two&quot;가 되면
            else if (temp == &quot;two&quot;)
            {
                // 숫자 2 추가
                answer += &#039;2&#039;;

                // temp 비우기
                temp = &quot;&quot;;
            }

            // temp가 &quot;three&quot;가 되면
            else if (temp == &quot;three&quot;)
            {
                // 숫자 3 추가
                answer += &#039;3&#039;;

