[ 해설 ]
#include &lt;iostream&gt; // cout 사용을 위한 헤더
#include &lt;vector&gt;   // vector 사용을 위한 헤더

using namespace std;

// 정수 벡터의 모든 원소를 더한 값을 반환하는 함수
// const : 함수 안에서 벡터를 수정하지 않겠다는 의미
// &amp;     : 벡터를 복사하지 않고 원본을 참조하여 성능 향상
// long long : 합계가 int 범위를 넘을 수 있으므로 더 큰 자료형 사용
long long sum(const vector&lt;int&gt;&amp; v)
{
    // 합계를 저장할 변수
    // 처음에는 아무것도 더하지 않았으므로 0으로 초기화
    long long sum1 = 0;

    // 범위 기반 for문(range-based for)
    // v 벡터의 원소를 처음부터 끝까지 하나씩 x에 저장하며 반복
    //
    // 1회전 : x = 3
    // 2회전 : x = 6
    // 3회전 : x = 7
    // 4회전 : x = 9
    for (int x : v)
    {
        // 현재 원소를 합계에 누적
        //
        // 1회전 : sum1 = 0 + 3 = 3
        // 2회전 : sum1 = 3 + 6 = 9
        // 3회전 : sum1 = 9 + 7 = 16
        // 4회전 : sum1 = 16 + 9 = 25
        sum1 += x;
    }

    // 반복이 끝난 후 최종 합계를 반환
    return sum1;
}

int main()
{
    // 정수 4개를 가진 벡터 생성
    vector&lt;int&gt; v{ 3, 6, 7, 9 };

    // sum 함수 호출
    // v의 모든 원소를 더한 결과를 출력
    //
    // 3 + 6 + 7 + 9 = 25
    cout &lt;&lt; sum(v) &lt;&lt; &quot;\n&quot;;

    return 0;
}
#include &lt;iostream&gt; // cout 사용
#include &lt;vector&gt;   // vector 사용

using namespace std;

// 정수 벡터 v의 모든 원소의 합을 반환하는 함수
//
// const : 함수 내부에서 v를 수정하지 않음
// &amp;     : 벡터를 복사하지 않고 원본을 참조함
// long long : 합계가 커질 수 있으므로 사용
long long sum(const vector&lt;int&gt;&amp; v)
{
    // 원소들의 합을 저장할 변수
    // 처음에는 합계가 없으므로 0으로 초기화
    long long sum1 = 0;

    // i를 0부터 시작하여
    // 벡터의 마지막 인덱스 전까지 반복
    for (int i = 0; i &lt; v.size(); i++)
    {
        // v[i] : i번째 원소
        //
        // i = 0 → v[0] = 3
        // i = 1 → v[1] = 6
        // i = 2 → v[2] = 7
        // i = 3 → v[3] = 9
        //
        // 각 원소를 sum1에 누적
        sum1 += v[i];

        /*
        반복 과정

        i=0 : sum1 = 0 + 3 = 3
        i=1 : sum1 = 3 + 6 = 9
        i=2 : sum1 = 9 + 7 = 16
        i=3 : sum1 = 16 + 9 = 25
        */
    }

    // 최종 합계 반환
    return sum1;
}

int main()
{
    // 정수 4개를 가진 벡터 생성
    vector&lt;int&gt; v{ 3, 6, 7, 9 };

    // sum 함수 호출 후 결과 출력
    // 3 + 6 + 7 + 9 = 25
    cout &lt;&lt; sum(v) &lt;&lt; &quot;\n&quot;;

    return 0;
}

