public:
    void setName(string name) { // 매개변수 name
        // name = name; (X) -&gt; 매개변수끼리 대입하는 의미 없는 코드가 됨
        this-&gt;name = name; // (O) -&gt; 진짜 내 멤버 변수에 매개변수 값을 대입!
    }
};
② 멤버 함수에서 객체 자신을 다시 반환할 때 (연속 호출)
class Counter {
private:
    int count = 0;
public:
    Counter&amp; add() {
        count++;
        return *this; // 내 객체 자체를 통째로 반환!
    }
};

// 사용 예시: 함수를 기차처럼 이어 붙여 쓸 수 있음
