구문의미실제 역할ptr (일반 포인터)내가 임의로 지정한 메모리 주소임의의 대상 변수를 원격 제어할 때 사용this (this 포인터)나 자신의 메모리 주소함수 내부에서 “지금 이 함수를 호출한 나 자신”을 의미*this나 자신의 실제 알맹이(객체)함수가 종료되면서 자기 자신을 반환할 때 사용

const 멤버 함수
멤버 변수 수정 불가능 :
함수 내부에서 멤버 변수의 값을 바꾸려고 하면 컴파일 에러가 발생
다른 일반 함수 호출 불가능 :
const 함수 안에서는 값을 바꿀지도 모르는 일반 멤버 함수를 호출할 수 없고, 오직 다른 const 멤버 함수만 호출할 수 있습니다.

#include &lt;iostream&gt;
using namespace std;

class Person {
public:
    int age = 20;

    // 1. const 함수 (읽기 전용 🔎)
    void printAge() const {
        // age = 30; // ❌ 에러! const 함수 내에서는 값을 바꿀 수 없습니다.
        cout &lt;&lt; age &lt;&lt; &quot;\n&quot;; // ⭕ 값을 읽어서 출력하는 것만 가능!
    }

    // 2. 일반 함수 (수정 가능 ✏️)
    void birthday() {
        age++; // ⭕ 값을 마음대로 바꿀 수 있음!
    }
};

int main() {
    Person p;
    p.printAge(); // 20 출력
    p.birthday(); // 나이 1살 증가
    p.printAge(); // 21 출력
}
