#include &lt;iostream&gt; // 입출력을 위한 헤더 파일 포함
using namespace std; // std:: 네임스페이스 생략 설정

class Rect { // 사각형을 정의하는 Rect 클래스 시작
private: // 외부에서 직접 접근할 수 없는 보호 영역
    int width;  // 사각형의 가로 길이를 저장하는 멤버 변수
    int height; // 사각형의 세로 길이를 저장하는 멤버 변수

public: // 외부(main 함수 등)에서 자유롭게 접근할 수 있는 개방 영역
    // 생성자: 객체가 생성될 때 가로, 세로 값을 받아 초기화합니다.
    Rect(int width, int height) 
    {
        // 기존의 &#039;this-&gt;width;&#039;는 변수를 부르기만 하고 값을 넣지 않는 오류였습니다.
        // 대입 연산자(=)를 써서 매개변수 width를 진짜 멤버 변수(this-&gt;width)에 채워줍니다.
        this-&gt;width = width;   
        this-&gt;height = height; // 매개변수 height의 값을 멤버 변수 height에 대입합니다.
    }

    // 사각형의 넓이를 구해서 반환하는 멤버 함수
    // 뒤에 붙은 const는 이 함수 안에서 width나 height 값을 절대 변경하지 않겠다는 의미입니다.
    int area() const
    {
       return width * height; // 가로 * 세로 계산 결과를 반환
    }

    // 가로 길이를 외부에서 새로 수정하는 함수
    void setWidth(int width)
    {
        // 만약 받아온 가로 길이(매개변수 width)가 0보다 작다면(음수라면)
        if (width &lt; 0) 
        {
            this-&gt;width = 0; // 사각형의 진짜 멤버 변수 가로 길이를 0으로 강제 세팅합니다.
        }
        // 그 외의 경우(0 이상인 정상적인 양수라면)
        else 
        {
            // 기존의 &#039;width = width;&#039;는 매개변수끼리 값을 주고받는 의미 없는 코드였습니다.
            // 명확하게 &#039;this-&gt;&#039;를 붙여서 진짜 멤버 변수에 매개변수 값을 대입해 줍니다.
            this-&gt;width = width; 
        }
    }

    // 세로 길이를 외부에서 새로 수정하는 함수
    void setHeight(int height)
    {
        // 입력받은 세로 길이가 음수인지 검사합니다.
        if (height &lt; 0) 
        {
            this-&gt;height = 0; // 음수 유입 시 데이터 왜곡을 막기 위해 0으로 안전하게 저장합니다.
        }
        // 입력받은 세로 길이가 정상적인 양수라면
        else 
        {
            this-&gt;height = height; // 전달받은 값을 진짜 멤버 변수 height에 대입합니다.
        }
    }
}; // 클래스 정의 종료 (세미콜론 필수)

int main() { // 프로그램의 시작점인 main 함수
    Rect r(3, 4); // 가로 3, 세로 4를 가지는 사각형 객체 r 생성 (생성자 호출됨)
    cout &lt;&lt; r.area() &lt;&lt; &quot;\n&quot;; // area() 함수가 3 * 4를 계산하여 12 출력

    r.setWidth(-5); // 음수인 -5를 전달 -&gt; setWidth 내부 조건문에 의해 가로(width)는 0이 됨
    r.setHeight(2); // 양수인 2를 전달 -&gt; 세로(height)는 정상적으로 2가 됨

    cout &lt;&lt; r.area() &lt;&lt; &quot;\n&quot;; // 가로가 0이 되었으므로 0 * 2를 계산하여 0 출력
}

