    GENERATED_BODY()  

public:  
    UFUNCTION()  
    virtual void OnItemOverlap(
          UPrimitiveComponent* OverlappedComp,  
          AActor* OtherActor,  
          UPrimitiveComponent* OtherComp,  
          int32 OtherBodyIndex,  
          bool bFromSweep,  
          const FHitResult&amp; SweepResult) = 0;

